CREATE TABLE "furniture_procurements" ("id" TEXT PRIMARY KEY, "business_id" TEXT NOT NULL, "custom_order_id" TEXT NOT NULL, "supplier_id" TEXT, "description" TEXT NOT NULL, "amount" DECIMAL(14,2) NOT NULL DEFAULT 0, "status" TEXT NOT NULL DEFAULT 'requested', "ordered_at" TIMESTAMP(3), "received_at" TIMESTAMP(3), "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "furniture_procurements_business_id_custom_order_id_status_idx" ON "furniture_procurements"("business_id","custom_order_id","status");
CREATE TABLE "furniture_returns" ("id" TEXT PRIMARY KEY, "business_id" TEXT NOT NULL, "custom_order_id" TEXT NOT NULL, "return_no" TEXT NOT NULL, "reason" TEXT NOT NULL, "resolution" TEXT, "status" TEXT NOT NULL DEFAULT 'open', "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "resolved_at" TIMESTAMP(3));
CREATE UNIQUE INDEX "furniture_returns_business_id_return_no_key" ON "furniture_returns"("business_id","return_no");
CREATE TABLE "furniture_installation_signoffs" ("id" TEXT PRIMARY KEY, "business_id" TEXT NOT NULL, "installation_id" TEXT NOT NULL, "customer_name" TEXT NOT NULL, "signature_reference" TEXT, "notes" TEXT, "signed_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX "furniture_installation_signoffs_business_id_installation_id_key" ON "furniture_installation_signoffs"("business_id","installation_id");
CREATE TABLE "workshop_inventory_postings" ("id" TEXT PRIMARY KEY, "business_id" TEXT NOT NULL, "job_card_id" TEXT NOT NULL, "product_id" TEXT NOT NULL, "quantity" DECIMAL(14,3) NOT NULL, "posting_type" TEXT NOT NULL, "idempotency_key" TEXT, "posted_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX "workshop_inventory_postings_business_id_idempotency_key_key" ON "workshop_inventory_postings"("business_id","idempotency_key");
CREATE TABLE "workshop_vehicle_deliveries" ("id" TEXT PRIMARY KEY, "business_id" TEXT NOT NULL, "job_card_id" TEXT NOT NULL, "delivered_to" TEXT NOT NULL, "signature_reference" TEXT, "notes" TEXT, "delivered_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX "workshop_vehicle_deliveries_business_id_job_card_id_key" ON "workshop_vehicle_deliveries"("business_id","job_card_id");
CREATE TABLE "wholesale_packing_list_items" ("id" TEXT PRIMARY KEY, "business_id" TEXT NOT NULL, "packing_list_id" TEXT NOT NULL, "sales_order_item_id" TEXT NOT NULL, "quantity" DECIMAL(14,3) NOT NULL, "unit" TEXT NOT NULL DEFAULT 'unit');
CREATE INDEX "wholesale_packing_list_items_business_id_packing_list_id_idx" ON "wholesale_packing_list_items"("business_id","packing_list_id");
CREATE TABLE "wholesale_proof_of_deliveries" ("id" TEXT PRIMARY KEY, "business_id" TEXT NOT NULL, "dispatch_id" TEXT NOT NULL, "receiver_name" TEXT NOT NULL, "signature_reference" TEXT, "notes" TEXT, "delivered_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX "wholesale_proof_of_deliveries_business_id_dispatch_id_key" ON "wholesale_proof_of_deliveries"("business_id","dispatch_id");
CREATE TABLE "wholesale_credit_profiles" ("id" TEXT PRIMARY KEY, "business_id" TEXT NOT NULL, "customer_id" TEXT NOT NULL, "credit_limit" DECIMAL(14,2) NOT NULL DEFAULT 0, "credit_days" INTEGER NOT NULL DEFAULT 0, "blocked" BOOLEAN NOT NULL DEFAULT false, "updated_at" TIMESTAMP(3) NOT NULL);
CREATE UNIQUE INDEX "wholesale_credit_profiles_business_id_customer_id_key" ON "wholesale_credit_profiles"("business_id","customer_id");
CREATE TABLE "release_d_notification_rules" ("id" TEXT PRIMARY KEY, "business_id" TEXT NOT NULL, "industry" TEXT NOT NULL, "event_code" TEXT NOT NULL, "enabled" BOOLEAN NOT NULL DEFAULT true, "days_before" INTEGER, "channel" TEXT NOT NULL DEFAULT 'in_app');
CREATE UNIQUE INDEX "release_d_notification_rules_business_id_industry_event_code_key" ON "release_d_notification_rules"("business_id","industry","event_code");
